public partial class WindowPicker:Window{[StructLayout(LayoutKind.Sequential)]struct P{public int X,Y;}[StructLayout(LayoutKind.Sequential)]struct R{public int Left,Top,Right,Bottom;}[DllImport("user32.dll")]static extern IntPtr WindowFromPoint(P p);[DllImport("user32.dll")]static extern IntPtr GetAncestor(IntPtr h,uint f);[DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr h,out R r);const uint GA_ROOT=2;IntPtr selected;public Rect Selection{get;private set;}public WindowPicker(){InitializeComponent();var v=Forms.SystemInformation.VirtualScreen;Left=v.Left;Top=v.Top;Width=v.Width;Height=v.Height;Loaded+=(_,_)=>{Activate();Focus();Keyboard.Focus(this);};}void Window_MouseMove(object s,System.Windows.Input.MouseEventArgs e){var p=Forms.Cursor.Position;selected=GetAncestor(WindowFromPoint(new P{X=p.X,Y=p.Y}),GA_ROOT);if(selected==IntPtr.Zero||!GetWindowRect(selected,out var r))return;Selection=new Rect(r.Left,r.Top,r.Right-r.Left,r.Bottom-r.Top);Canvas.SetLeft(Highlight,r.Left-Left);Canvas.SetTop(Highlight,r.Top-Top);Highlight.Width=Selection.Width;Highlight.Height=Selection.Height;}void Window_MouseLeftButtonUp(object s,System.Windows.Input.MouseButtonEventArgs e){DialogResult=Selection.Width>1;}void Window_KeyDown(object s,System.Windows.Input.KeyEventArgs e){if(e.Key==Key.Escape){DialogResult=false;Close();}}}
